// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.callimport timber.log.Timberimport com.roshan.persona.connectivity.model.SpamClassificationimport com.roshan.persona.connectivity.model.SpamLevelimport com.roshan.persona.connectivity.model.SpamSourceimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Spam Detector Engine (Module 11 v3 — Step 11.3, CRITICAL). * * Detects spam calls using 4 strategies (all on-device, privacy-first): * *  1. **Local DB lookup** — check against user-reported + community spam numbers. *  2. **Pattern detection** — 200 calls in 1 hour = spam; 5 calls in 1 min = spam. *  3. **Contact list check** — if caller is in contacts, lower spam risk. *  4. **ML classifier** (v2+) — on-device model classifies voice patterns. * * ## Decision matrix * * | Source | Spam Level | Action | * |--------|-----------|--------| * | Local DB (user-reported) | SPAM | Auto-block (if configured) | * | Pattern (>100 calls/hour) | HIGH_RISK | Auto-block | * | Pattern (>10 calls/hour) | SUSPICIOUS | Ask user | * | Not in contacts + unknown | LOW_RISK | ActiveCallBouncer (v3) | * | In contacts | SAFE | Normal ring | * * ## Privacy * * All detection is on-device. No phone numbers are sent to any server. * The community spam DB is downloaded via secure patches (signed, encrypted). * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§SpamDetectorEngine</a> */class SpamDetectorEngine(    private val spamDb: SpamDatabase,    private val contactChecker: (String) -> Boolean,    private val dispatcher: CoroutineDispatcher,) {    /**     * Classify a phone number for spam risk.     *     * Called by [CallEngine] when an incoming call is detected (RINGING).     * Must return quickly (< 50ms target) — the phone is ringing.     *     * @param phoneNumber the incoming caller's phone number.     * @return the spam classification.     */    suspend fun classify(phoneNumber: String): SpamClassification = withContext(dispatcher) {        val normalized = normalizeNumber(phoneNumber)        // 1. Check local spam database.        val dbResult = spamDb.lookup(normalized)        if (dbResult != null) {            Timber.tag(TAG).d("Spam DB hit: $normalized → ${dbResult.level}")            return@withContext dbResult        }        // 2. Check contact list — contacts are always HAM (known-good).        if (contactChecker(normalized)) {            return@withContext SpamClassification(                phoneNumber = normalized,                level = SpamLevel.HAM,                confidence = 1.0f,                reason = "Number is in your contacts",                source = SpamSource.CONTACT_LIST,            )        }        // 3. Pattern detection — check call frequency.        val callCount1h = spamDb.getCallCount(normalized, hours = 1)        val patternResult = checkPattern(normalized, callCount1h)        if (patternResult != null) {            return@withContext patternResult        }        // 4. Unknown — not in contacts, not in spam DB, no pattern.        //    Fall back to the legacy LOW_RISK label so the CallEngine can        //    route it to the Bouncer (Strategy §"ActiveCallBouncer" expects        //    unknown numbers to be intercepted).        @Suppress("DEPRECATION")        return@withContext SpamClassification(            phoneNumber = normalized,            level = SpamLevel.LOW_RISK,            confidence = 0.3f,            reason = "Unknown number not in contacts or spam database",            source = SpamSource.PATTERN,        )    }    /**     * Pattern-based spam detection.     *     * Checks call frequency patterns:     *  - > 100 calls in 1 hour → SPAM (telemarketer auto-dialer)     *  - > 20 calls in 1 hour → FRAUD (escalated pattern — likely scam)     *  - > 10 calls in 1 hour → SUSPECT     *  - ≤ 10 calls in 1 hour → null (no pattern detected, continue)     */    internal fun checkPattern(phoneNumber: String, callCount1h: Int): SpamClassification? {        return when {            callCount1h > 100 -> SpamClassification(                phoneNumber = phoneNumber,                level = SpamLevel.SPAM,                confidence = 0.95f,                reason = "Pattern: $callCount1h calls in 1 hour (auto-dialer)",                source = SpamSource.PATTERN,            )            callCount1h > 20 -> SpamClassification(                phoneNumber = phoneNumber,                level = SpamLevel.FRAUD,                confidence = 0.85f,                reason = "Pattern: $callCount1h calls in 1 hour (escalated)",                source = SpamSource.PATTERN,            )            callCount1h > 10 -> SpamClassification(                phoneNumber = phoneNumber,                level = SpamLevel.SUSPECT,                confidence = 0.7f,                reason = "Pattern: $callCount1h calls in 1 hour",                source = SpamSource.PATTERN,            )            else -> null        }    }    /**     * Report a number as spam (user-initiated — "Mark this number as spam").     */    suspend fun reportSpam(phoneNumber: String, reason: String = "User-reported") = withContext(dispatcher) {        spamDb.reportSpam(normalizeNumber(phoneNumber), reason)        Timber.tag(TAG).i("User reported $phoneNumber as spam: $reason")    }    /**     * Remove a number from spam (false positive — "This is not spam").     */    suspend fun removeFromSpam(phoneNumber: String): Boolean = withContext(dispatcher) {        val removed = spamDb.removeFromSpam(normalizeNumber(phoneNumber))        if (removed) Timber.tag(TAG).i("Removed $phoneNumber from spam database.")        removed    }    /**     * Record that a call was received (for pattern detection).     * Called by CallStateMonitor on every incoming call.     */    suspend fun recordIncomingCall(phoneNumber: String, timestampMs: Long = System.currentTimeMillis()) = withContext(dispatcher) {        spamDb.recordCall(normalizeNumber(phoneNumber), timestampMs)    }    /** Normalize phone number — digits only. */    internal fun normalizeNumber(phone: String): String = phone.filter { it.isDigit() }    private companion object {        private const val TAG = "SpamDetector"    }}